select energy_manager.load_cards($cards$[
{"kind":"problem","topic":"Financial Analysis","front":"Two projects each cost Rs 30,000 and run for 10 years at an 8% discount rate. Project 1 saves Rs 6,000 a year. Project 2 saves 6,600, 6,600, 6,300, 6,300, 6,000, 6,000, 5,700, 5,700, 5,400 and 5,400 in years 1 to 10. Which project has the higher NPV?","back":"NPV of Project 1 = Rs 10,254.00; NPV of Project 2 = Rs 10,867.80. Project 2 is preferred.","explain":"Example 10.6 of the chapter. Both projects give a positive NPV at 8%, but Project 2 has the higher value.","flash":false,"source":"BEE Book 4 Ch 10 p193","steps":[{"prompt":"Note the discount factors at 8%.","answer":"Years 1 to 10: 0.926, 0.857, 0.794, 0.735, 0.681, 0.630, 0.583, 0.540, 0.500, 0.463.","explain":"Discount factor = 1 / (1.08)^n."},{"prompt":"Find Project 1's NPV.","answer":"PV of savings = 6,000 × sum of factors = Rs 40,254; NPV = 40,254 - 30,000 = Rs 10,254.","explain":"Project 1 saves the same amount each year."},{"prompt":"Find Project 2's NPV.","answer":"PV of savings = Rs 40,867.80; NPV = 40,867.80 - 30,000 = Rs 10,867.80.","explain":"Front-loaded savings are worth more in present value."},{"prompt":"Compare.","answer":"Project 2 has the higher NPV, so it is the preferred proposal.","explain":"A higher NPV means a more attractive project."}],"id":"p4-b10-027","paper":4,"order":4441},
{"kind":"problem","topic":"Financial Analysis","front":"A project needs Rs 20,000 of capital. Its cash flows for years 1 to 6 are 6,000, 5,500, 5,000, 4,500, 4,000 and 4,000. Find its IRR.","back":"IRR = 12.93%.","explain":"Example 10.7 of the chapter. NPV is positive at 12% and negative at 16%, so the zero point lies between them.","flash":false,"source":"BEE Book 4 Ch 10 p195","steps":[{"prompt":"Find the NPV at 12%.","answer":"PV of inflows = Rs 20,459.50; NPV = +Rs 459.50.","explain":"Multiply each cash flow by its discount factor at 12%."},{"prompt":"Find the NPV at 16%.","answer":"PV of inflows = Rs 18,491.50; NPV = -Rs 1,508.50.","explain":"The NPV has changed sign, so the IRR lies between 12% and 16%."},{"prompt":"Interpolate.","answer":"IRR = 12 + (16 - 12) × 459.5 / (459.5 + 1508.5) = 12.93%.","explain":"Linear interpolation between the two rates."},{"prompt":"Check the result.","answer":"NPV at 8% is +Rs 2,791, which is consistent with a higher IRR.","explain":"NPV falls as the discount rate rises."}],"id":"p4-b10-028","paper":4,"order":4442},
{"kind":"problem","topic":"Financial Analysis","front":"Using the NPVs from Example 10.6 (Rs 10,254 for Project 1 and Rs 10,867.80 for Project 2) and a capital cost of Rs 30,000 for each, find the profitability index of each project.","back":"PI Project 1 = 0.342; PI Project 2 = 0.362. Project 2 is the better proposal.","explain":"Example 10.8 of the chapter. The book uses the NPV values as the discounted net savings in the numerator.","flash":false,"source":"BEE Book 4 Ch 10 p196","steps":[{"prompt":"Calculate Project 1's PI.","answer":"10,254 / 30,000 = 0.342.","explain":"Numerator is the discounted net savings from Example 10.6."},{"prompt":"Calculate Project 2's PI.","answer":"10,867.80 / 30,000 = 0.362.","explain":"Same capital cost, higher numerator."},{"prompt":"Compare.","answer":"Project 2 has the higher index, so it is the better proposal.","explain":"A higher profitability index means a more attractive project."}],"id":"p4-b10-029","paper":4,"order":4443},
{"kind":"problem","topic":"Financial Analysis","front":"A heat recovery unit costs Rs 20,000 and has a salvage value of Rs 1,500 after 5 years. Savings are 7,000, 6,000, 6,000, 5,000 and 5,000 in years 1 to 5. The discount rate is 8%. Find the NPV with and without the salvage value.","back":"NPV with salvage = Rs 4,489.50; NPV without salvage = Rs 3,468.","explain":"Example 10.9 of the chapter. Salvage value raises the NPV by Rs 1,021.50, the discounted value of Rs 1,500 in year 5.","flash":false,"source":"BEE Book 4 Ch 10 p197","steps":[{"prompt":"Find the discount factors at 8%.","answer":"Years 1 to 5: 0.926, 0.857, 0.794, 0.735, 0.681.","explain":"Discount factor = 1 / (1.08)^n."},{"prompt":"Find the PV of savings in years 1 to 4.","answer":"6,482 + 5,142 + 4,764 + 3,675 = Rs 20,063.","explain":"Each saving multiplied by its factor."},{"prompt":"Find the PV of year 5, including salvage.","answer":"(5,000 + 1,500) × 0.681 = Rs 4,426.50.","explain":"Salvage is received in year 5 with the final saving."},{"prompt":"Find the NPV with salvage.","answer":"20,063 + 4,426.50 - 20,000 = Rs 4,489.50.","explain":"Subtract the capital cost."},{"prompt":"Find the NPV without salvage.","answer":"4,489.50 - 1,500 × 0.681 = Rs 3,468.","explain":"Remove the discounted salvage value."}],"id":"p4-b10-030","paper":4,"order":4444},
{"kind":"problem","topic":"Financial Analysis","front":"Recalculate the NPV of the heat recovery scheme in Example 10.9 with the discount rate kept at 8% and inflation at 5%.","back":"Real interest rate = 3%; NPV = Rs 4,397.88, down from Rs 4,489.50.","explain":"Example 10.10 of the chapter. The book's table shows 4,145 for year-4 real savings, which is a typo: 5,000 × 0.823 = 4,115, and the book's PV of 3,654.12 uses 4,115.","flash":false,"source":"BEE Book 4 Ch 10 p198","steps":[{"prompt":"Find the real interest rate.","answer":"8 - 5 = 3%.","explain":"Real interest rate = discount rate - inflation rate."},{"prompt":"Find the inflation factors at 5%.","answer":"Years 1 to 5: 0.952, 0.907, 0.864, 0.823, 0.784.","explain":"Inflation factor = (1.05)^(-n)."},{"prompt":"Find the real savings.","answer":"Year 1: 6,664; year 2: 5,442; year 3: 5,184; year 4: 4,115; year 5: (5,000 + 1,500) × 0.784 = 5,096.","explain":"Each cash flow multiplied by its inflation factor."},{"prompt":"Discount at the real rate of 3%.","answer":"Factors 0.971, 0.943, 0.915, 0.888, 0.863 give PVs of 6,470.74, 5,131.81, 4,743.36, 3,654.12 and 4,397.85.","explain":"Discounting real savings at the real interest rate."},{"prompt":"Find the NPV.","answer":"-20,000 + 24,397.88 = Rs 4,397.88.","explain":"Lower than the Rs 4,489.50 of Example 10.9."}],"id":"p4-b10-031","paper":4,"order":4445},
{"kind":"problem","topic":"Financial Analysis","front":"Two energy conservation projects each need Rs 1,50,000. Project 1 saves Rs 50,000 a year for 5 years with nil salvage. Project 2 saves Rs 50,000 in years 1 and 2, Rs 60,000 in years 3 to 5, and has a salvage value of Rs 10,000 at year 5. At a 9% discount factor, find the NPV, profitability index and IRR of each.","back":"NPV: Project 1 = Rs 44,483; Project 2 = Rs 72,287. PI: 0.297 and 0.481. IRR: 19.86% and 25.07%.","explain":"Solved example (i) from the chapter. Project 2 is better on all three measures.","flash":false,"source":"BEE Book 4 Ch 10 p199","steps":[{"prompt":"Find Project 1's NPV.","answer":"-1,50,000 + 50,000 × (1/1.09 + ... + 1/1.09^5) = +Rs 44,483.","explain":"Five equal savings discounted at 9%."},{"prompt":"Find Project 2's NPV.","answer":"-1,50,000 + 50,000/1.09 + 50,000/1.09^2 + 60,000/1.09^3 + 60,000/1.09^4 + 60,000/1.09^5 + 10,000/1.09^5 = +Rs 72,287.","explain":"Salvage is discounted over 5 years like the final saving."},{"prompt":"Find the profitability indices.","answer":"Project 1: 44,483 / 1,50,000 = 0.297. Project 2: 72,287 / 1,50,000 = 0.481.","explain":"PI = discounted net savings divided by capital cost."},{"prompt":"Find the IRRs.","answer":"Project 1 = 19.86%; Project 2 = 25.07%.","explain":"The discount rate that makes NPV zero for each project."}],"id":"p4-b10-032","paper":4,"order":4446},
{"kind":"problem","topic":"Financial Analysis","front":"A VFD retrofit in a compressed air system costs Rs 2.55 lakh and saves Rs 58,000 a year over six years. The NPV is +Rs 13,134 at 8% and -Rs 2,468 at 10%. Find the discount rate at which NPV is zero.","back":"About 9.68%.","explain":"Solved example (ii) from the chapter. The result is an interpolated estimate of the IRR.","flash":false,"source":"BEE Book 4 Ch 10 p199","steps":[{"prompt":"Identify the bracketing rates.","answer":"NPV is positive at 8% (+13,134) and negative at 10% (-2,468).","explain":"Zero lies between the two rates."},{"prompt":"Interpolate.","answer":"8 + (10 - 8) × 13,134 / (13,134 + 2,468) = 8 + 2 × 0.842 = 9.68%.","explain":"Linear interpolation of NPV against discount rate."},{"prompt":"Check against the book.","answer":"The book's solution gives 9.68%.","explain":"Confirms the interpolation."}],"id":"p4-b10-033","paper":4,"order":4447},
{"kind":"problem","topic":"Financial Analysis","front":"A heat recovery unit costs Rs 20,000 and saves a constant Rs 5,000 a year for 5 years. The discount rate is 8%. Calculate the NPV.","back":"NPV is about -Rs 36, essentially zero. At 8% the unit just fails to recover its cost.","explain":"End-of-chapter question L-2. The IRR is just below 8%.","flash":false,"source":"BEE Book 4 Ch 10 p200","steps":[{"prompt":"Find the annuity factor.","answer":"(1 - 1.08^-5) / 0.08 = 3.9927.","explain":"Sum of the discount factors for years 1 to 5 at 8%."},{"prompt":"Find the PV of savings.","answer":"5,000 × 3.9927 = Rs 19,963.50.","explain":"Equal savings each year."},{"prompt":"Find the NPV.","answer":"19,963.50 - 20,000 = about -Rs 36.","explain":"Negative NPV means the project does not meet the 8% rate."}],"id":"p4-b10-034","paper":4,"order":4448},
{"kind":"problem","topic":"Financial Analysis","front":"A waste heat recovery system costs Rs 6,50,000 and has a 6-year life with salvage value Rs 1,00,000. It saves Rs 1,40,000 a year in years 1 to 3 (70% of full-load savings of Rs 2,00,000) and Rs 2,00,000 a year in years 4 to 6. Maintenance is Rs 10,000 a year in years 1 to 3 and Rs 12,000 a year in years 4 to 6. A Rs 1,00,000 overhaul falls in year 3. At a 9% discount rate, find the NPV and say whether the measure is profitable.","back":"NPV is about Rs 29,000, so the measure is profitable at 9%.","explain":"End-of-chapter question N-1, worked from the chapter's NPV formula. Assumes the capital is spent at year 0, the overhaul is at the end of year 3, and salvage is received at the end of year 6. The profitability index part of the question is not carded.","flash":false,"source":"BEE Book 4 Ch 10 p200","steps":[{"prompt":"Find the net cash flow in each year.","answer":"Year 1: 1,40,000 - 10,000 = 1,30,000; year 2: 1,30,000; year 3: 1,40,000 - 10,000 - 1,00,000 = 30,000; year 4: 2,00,000 - 12,000 = 1,88,000; year 5: 1,88,000; year 6: 1,88,000 + 1,00,000 salvage = 2,88,000.","explain":"Include maintenance, overhaul and salvage in the year they occur."},{"prompt":"Find the discount factors at 9%.","answer":"Years 1 to 6: 0.9174, 0.8417, 0.7722, 0.7084, 0.6499, 0.5963.","explain":"Discount factor = 1 / (1.09)^n."},{"prompt":"Find the PV of net cash flows.","answer":"Sum of PVs is about Rs 6,78,950.","explain":"Each year's net cash flow multiplied by its factor."},{"prompt":"Find the NPV.","answer":"6,78,950 - 6,50,000 = about Rs 28,950, or about Rs 29,000.","explain":"Subtract the capital cost at year 0."},{"prompt":"Decide.","answer":"NPV is positive, so the measure is profitable at 9%.","explain":"A positive NPV at the discount rate means the project is worthwhile."}],"id":"p4-b10-035","paper":4,"order":4449},
{"kind":"problem","topic":"Financial Analysis","front":"A heat exchanger costs Rs 1,00,000. It saves Rs 60,000 a year, and its annual operating cost is Rs 15,000. Calculate the simple payback period.","back":"About 2.22 years.","explain":"End-of-chapter question S-8. Simple payback uses the annual net saving after operating costs.","flash":false,"source":"BEE Book 4 Ch 10 p200","steps":[{"prompt":"Find the net annual saving.","answer":"60,000 - 15,000 = Rs 45,000.","explain":"Savings less annual operating cost."},{"prompt":"Find the payback period.","answer":"PB = 1,00,000 / 45,000 = 2.22 years.","explain":"Capital cost divided by annual net saving."},{"prompt":"Check the meaning of the result.","answer":"Rs 45,000 a year recovers Rs 1,00,000 in about 2.22 years.","explain":"Payback is the time to recover the capital from net savings."}],"id":"p4-b10-036","paper":4,"order":4450},
{"id":"p4-b11-001","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"What is Gross Heat Rate (GHR) and at what point is it measured?","back":"GHR is the heat energy input in kcal required to generate one kWh of electrical energy, measured at the generator terminals.","explain":"GHR is the fuel heat input divided by gross generation, so no station auxiliaries have been deducted yet. For the same plant the net heat rate is always higher than the gross heat rate.","flash":true,"source":"BEE Book 4 Ch 11 p203","order":4451},
{"id":"p4-b11-002","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"Where is Net Heat Rate (NHR) measured, and what does it deduct from the gross figure?","back":"NHR is the heat input in kcal needed to deliver one kWh at the switchyard, so it deducts the station's own auxiliary power consumption.","explain":"Net output is what the grid receives, so fans, pumps and mills count against the plant. This is why NHR is higher than GHR for the same unit.","flash":false,"source":"BEE Book 4 Ch 11 p203","order":4452},
{"id":"p4-b11-003","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"How is Plant Load Factor (PLF) calculated?","back":"PLF (%) = energy generated in the period (MWh) ÷ [total capacity (MW) × total hours in the same period] × 100.","explain":"PLF compares actual generation with the maximum the plant could have delivered over the same period. Both terms must cover the same time window.","flash":false,"source":"BEE Book 4 Ch 11 p203","order":4453},
{"id":"p4-b11-004","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"How does the Indian definition express auxiliary energy consumption, and on what base?","back":"It is the energy used by the station's auxiliary equipment plus transformer losses inside the station, expressed as a percentage of the gross energy at the generator terminals of all units.","explain":"The base is the sum over all units of the station, not a single unit. Transformer losses inside the station are counted together with the auxiliaries.","flash":false,"source":"BEE Book 4 Ch 11 p203","order":4454},
{"id":"p4-b11-005","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"What is the formula linking net heat rate to gross heat rate and auxiliary power?","back":"NHR = GHR ÷ (1 − auxiliary power consumption % ÷ 100).","explain":"If 7% of gross generation is used internally, only 93% reaches the switchyard, so heat per delivered kWh rises by a factor of 1/0.93. Use this relation to convert between the two rates.","flash":true,"source":"BEE Book 4 Ch 11 p207","order":4455},
{"id":"p4-b11-006","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"What is overall efficiency of a power plant on a fuel-input basis?","back":"Overall efficiency (%) = generator output (kW) ÷ [fuel mass flow (kg/s) × gross calorific value (kJ/kg)] × 100.","explain":"The term counts only useful electrical output against the heat in the fuel. Using the heat rate instead, overall efficiency = 860 ÷ GHR (kcal/kWh) × 100.","flash":false,"source":"BEE Book 4 Ch 11 p207","order":4456},
{"id":"p4-b11-007","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"How is specific fuel consumption (SFC) defined?","back":"SFC (kg/kWh) = total fuel consumed (kg) ÷ gross generation (kWh).","explain":"SFC is like heat rate but expressed as fuel mass per unit of output. It uses gross generation, so it is comparable across plants only when the same definition is used.","flash":false,"source":"BEE Book 4 Ch 11 p207","order":4457},
{"id":"p4-b11-008","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"Why is reheat used in a thermal power plant's steam cycle?","back":"Reheating partially expanded steam raises the average temperature of heat addition, which increases cycle efficiency and extracts more work from the steam.","explain":"The added work is greater than the extra heat rejected, so net gain is positive. Reheat also keeps the steam from condensing during expansion, which can seriously damage turbine blades.","flash":false,"source":"BEE Book 4 Ch 11 p204","order":4458},
{"id":"p4-b11-009","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"In a typical 210 MW unit, what are the approximate HP exhaust and reheat temperatures?","back":"HP exhaust steam at about 36 kg/cm² and about 336 °C is reheated to roughly 535 °C, close to the main steam superheat temperature.","explain":"The reheated steam then goes to the intermediate pressure turbine to complete its expansion. These figures come from the chapter's 210 MW example.","flash":true,"source":"BEE Book 4 Ch 11 p204","order":4459},
{"id":"p4-b11-010","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"What is regenerative feed water heating, and where does the heating steam come from?","back":"Steam extracted from the turbine heats condensate and feed water in LP and HP heaters before the boiler. HP heaters take steam from the HP turbine (36 kg/cm²) and IP turbine (16 kg/cm²); LP heaters take it from LP turbine stages.","explain":"Heating feed water from within the cycle raises the average temperature of heat addition. Each extraction adds an incremental heat-transfer step, which improves efficiency compared with heating everything in the boiler.","flash":false,"source":"BEE Book 4 Ch 11 p205","order":4460},
{"id":"p4-b11-011","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"Name the six major areas for performance testing in a thermal power plant.","back":"Fuel handling and preparation (coal handling, mills); boilers and associated parts; turbines and associated parts; draft system and fans; condensers; and water pumping systems.","explain":"Each area is tested for its own efficiency and power use, so a station-wide deviation can be traced to the area responsible.","flash":false,"source":"BEE Book 4 Ch 11 p209","order":4461},
{"id":"p4-b11-012","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"Which single auxiliary consumer is the largest in a thermal plant, and what share can it take?","back":"The boiler feed pump (BFP), which may constitute more than 20% of total auxiliary power consumption.","explain":"Because of its size, the BFP is a priority in pumping assessments. Compare its actual values with design or performance-guarantee values.","flash":true,"source":"BEE Book 4 Ch 11 p218","order":4462},
{"id":"p4-b11-013","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"How is coal flow to a pulverised-coal line established during a mill performance test?","back":"By a dirty Pitot tube test on the pulverised coal lines, or from calibrated on-line coal feeder values where available.","explain":"The Pitot test also reveals unbalancing or choking in the pulverised coal lines. Airflow per PA fan is measured separately by the clean-air Pitot tube method.","flash":false,"source":"BEE Book 4 Ch 11 p211","order":4463},
{"id":"p4-b11-014","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"What coal fineness should a pulverised-fuel boiler achieve for good combustion?","back":"Over 80% of the fine coal should pass through 200 mesh.","explain":"Mill output fineness is monitored at regular intervals, and a fall in fineness triggers a review of maintenance practices. Mill rejects are analysed alongside it.","flash":true,"source":"BEE Book 4 Ch 11 p214","order":4464},
{"id":"p4-b11-015","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"How is air leakage into the air preheater estimated from oxygen readings?","back":"Air leakage % = (O₂ at APH outlet − O₂ at APH inlet) ÷ (21 − O₂ % in the gas leaving the APH) × 100.","explain":"The chapter's formula is partly garbled in the OCR, so the numerator here is the standard O₂ difference between outlet and inlet. The denominator is the excess-air term (21 − O₂).","flash":false,"source":"BEE Book 4 Ch 11 p216","order":4465},
{"id":"p4-b11-016","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"How often and where is oxygen measured to check air infiltration in the draft system?","back":"Once a month, before and after the air preheater, before and after the ESP, and before and after the ID fan.","explain":"The oxygen difference across each unit shows where air is entering. Gas quantity is then estimated and compared with design or best-run values for that load.","flash":false,"source":"BEE Book 4 Ch 11 p217","order":4466},
{"id":"p4-b11-017","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"What is the practical lower TTD limit for a feed water heater without a desuperheating zone?","back":"+1.1 °C.","explain":"The chapter gives this as the practical lower limit for a heater with no desuperheating zone. With a desuperheating zone, TTD can be negative instead.","flash":true,"source":"BEE Book 4 Ch 11 p219","order":4467},
{"id":"p4-b11-018","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"Can the terminal temperature difference of a feed water heater be negative?","back":"Yes, if the heater has a desuperheating zone, the feed water leaving can be hotter than the condensing saturation temperature.","explain":"The negative TTD limit depends on how much superheat the extraction steam carries into the heater. Removing the desuperheating zone makes the TTD positive.","flash":false,"source":"BEE Book 4 Ch 11 p219","order":4468},
{"id":"p4-b11-019","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"What does an increase in a feed water heater's TTD and DCA, compared with design, indicate?","back":"A drop in heat transfer, mainly due to fouling.","explain":"Higher TTD and DCA mean the cycle is less efficient, which raises heat rate and fuel cost. Lower values are better.","flash":false,"source":"BEE Book 4 Ch 11 p220","order":4469},
{"id":"p4-b11-020","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"Which standard is referred to for assessing steam turbine performance?","back":"ASME PTC-6S, the steam turbine performance test code.","explain":"The chapter uses it as the reference for turbine heat rate, cycle efficiency and stage efficiency assessments.","flash":true,"source":"BEE Book 4 Ch 11 p220","order":4470},
{"id":"p4-b11-021","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"What is the turbine cycle (thermal) efficiency formula?","back":"Turbine cycle efficiency (%) = 860 ÷ turbine heat rate (kcal/kWh) × 100.","explain":"It is the reciprocal of heat rate in consistent units, since 860 kcal is the heat equivalent of one kWh.","flash":false,"source":"BEE Book 4 Ch 11 p222","order":4471},
{"id":"p4-b11-022","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"How is turbine stage (isentropic) efficiency calculated, and how is each section tested?","back":"Stage efficiency % = actual enthalpy drop ÷ isentropic enthalpy drop × 100. Each turbine section is tested and trended separately over the normal operating load range.","explain":"This enthalpy-drop method gives a good measure for monitoring. Testing each section on its own shows which section has deteriorated.","flash":false,"source":"BEE Book 4 Ch 11 p222","order":4472},
{"id":"p4-b11-023","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"Name five factors to check when turbine efficiency falls below design.","back":"Any five of: main and reheat steam inlet parameters; turbine exhaust parameters; reheater and superheater spray; boiler loading and performance; silica deposition; nozzle blockage; blade erosion; inter-stage and gland sealing; HP heater status.","explain":"The chapter lists these as the major factors to examine once turbine heat rate and efficiency have been compared with design.","flash":false,"source":"BEE Book 4 Ch 11 p222","order":4473},
{"id":"p4-b11-024","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"How is condenser terminal temperature difference (TTD) defined?","back":"TTD = Tsat − Tcwo, where Tsat is the saturation temperature at the condenser back pressure and Tcwo is the cooling water outlet temperature.","explain":"A higher TTD means less heat transfer is taking place inside the condenser. Monitor it against design or first-commissioning values.","flash":true,"source":"BEE Book 4 Ch 11 p225","order":4474},
{"id":"p4-b11-025","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"How is condenser effectiveness calculated?","back":"Effectiveness % = (Tcwo − Tcwi) ÷ (Tsat − Tcwi) × 100, which is the actual cooling water temperature rise over the maximum possible rise.","explain":"Higher effectiveness means the cooling water is taking more of the available heat. Tsat is the saturation temperature at the condenser back pressure.","flash":false,"source":"BEE Book 4 Ch 11 p225","order":4475},
{"id":"p4-b11-026","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"What is the condenser heat load formula?","back":"Heat load (kcal/hr) = Q × Cp × ΔT, where Q is cooling water flow (kg/hr), Cp is specific heat of water (kcal/kg °C) and ΔT is the cooling water temperature rise (°C).","explain":"This is the heat the cooling water removes from the condensing steam. If steam-table values are in kJ, convert with 1 kcal = 4.18 kJ so the units match.","flash":false,"source":"BEE Book 4 Ch 11 p225","order":4476},
{"id":"p4-b11-027","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"For a 210 MW unit, roughly how much does heat rate rise as condenser back pressure goes from 0.07 to 0.14 ata?","back":"From about 1960 to about 2050 kcal/kWh, a rise of roughly 90 kcal/kWh.","explain":"The 500 MW unit shows the same trend, from about 1975 to 2040 kcal/kWh over the same range. The chapter stresses that even a 0.01 kg/cm² (a) change in back pressure matters.","flash":false,"source":"BEE Book 4 Ch 11 p228","order":4477},
{"id":"p4-b11-028","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"Name five reasons for low condenser vacuum.","back":"Reduced cooling water flow; higher cooling water inlet temperature; tube fouling or scaling; gas accumulation; large thermal load; tube flooding; or improper functioning of the steam jet air ejector.","explain":"Use the fault chart to narrow it down: a high cooling water temperature rise points to flow or load, a high TTD to fouling, and a rising Tsat minus condensate temperature with more dissolved oxygen to air ingress.","flash":false,"source":"BEE Book 4 Ch 11 p229","order":4478},
{"id":"p4-b11-029","paper":4,"topic":"Thermal power station performance","kind":"fact","front":"A rise in Tsat minus condensate temperature, together with more dissolved oxygen in the condensate, indicates what?","back":"Air ingress into the condenser, through leaky valves, pipe fittings, instrument tappings or a faulty steam jet air ejector.","explain":"The fault chart uses this pattern to point to air leaks. Air ingress raises back pressure and cuts turbine output.","flash":false,"source":"BEE Book 4 Ch 11 p229","order":4479},
{"id":"p4-b11-030","paper":4,"topic":"Thermal power station performance","kind":"problem","front":"A coal mill draws 351 kW while handling 48.64 TPH of coal and 112.6 TPH of air. Find its air-to-coal ratio and specific energy consumption.","back":"Air-to-coal ratio = 2.31 kg air per kg coal. Specific energy consumption = 7.22 kWh per tonne of coal.","explain":"These are the two mill indicators the chapter asks auditors to establish. Both come straight from the mill's flow and power readings.","flash":false,"source":"BEE Book 4 Ch 11 p212","steps":[{"prompt":"Form the air-to-coal ratio from the two flows.","answer":"112.6 ÷ 48.64 = 2.31 kg of air per kg of coal (both flows are in TPH, so the ratio is unitless).","explain":"Both flows must be in the same units, and TPH on both sides lets the ratio be read directly as kg/kg."},{"prompt":"Find the specific energy consumption of the mill.","answer":"SEC = power (kW) ÷ coal flow (TPH) = 351 ÷ 48.64 = 7.22 kWh per tonne of coal.","explain":"Dividing kW by tonnes per hour gives kWh per tonne directly."},{"prompt":"What does the 7.22 figure tell the auditor?","answer":"The electrical energy the mill needs to grind one tonne of coal, which is the benchmark for comparing mills.","explain":"SEC lets mills be compared regardless of their throughput."}],"order":4480}
]$cards$::jsonb);
